package org.apache.commons.math3.optimization.univariate;

import org.apache.commons.math3.analysis.UnivariateFunction;
import org.apache.commons.math3.optimization.GoalType;
import org.apache.commons.math3.optimization.ConvergenceChecker;
import org.apache.commons.math3.optimization.SimpleUnivariateValueChecker;
import org.apache.commons.math3.optimization.univariate.BrentOptimizer;
import org.apache.commons.math3.optimization.univariate.UnivariatePointValuePair;
import org.junit.Test;
import static org.junit.Assert.*;

public class AgentBRT_Math_24_raw_diff_Test {

    @Test
    public void testReproduceBug() {
        // Define a simple quadratic function for testing
        UnivariateFunction function = new UnivariateFunction() {
            public double value(double x) {
                return (x - 2) * (x - 2);
            }
        };

        // Create a BrentOptimizer instance
        BrentOptimizer optimizer = new BrentOptimizer(1e-10, 1e-14);

        // Set a convergence checker
        ConvergenceChecker<UnivariatePointValuePair> checker = new SimpleUnivariateValueChecker(1e-10, 1e-14);
        optimizer.setConvergenceChecker(checker);

        // Perform optimization
        UnivariatePointValuePair result = optimizer.optimize(100, function, GoalType.MINIMIZE, -10.0, 10.0);

        // The expected minimum is at x = 2, f(x) = 0
        assertEquals(2.0, result.getPoint(), 1e-8);
        assertEquals(0.0, result.getValue(), 1e-8);
    }
}

